insert into public.exam_defs(stage,minutes,items) values (3,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "doctor", "b": "soldier", "c": "waiter"}}, {"n": 2, "opts": {"a": "June", "b": "September", "c": "July"}}, {"n": 3, "opts": {"a": "apples", "b": "bananas", "c": "oranges"}}, {"n": 4, "opts": {"a": "a photo", "b": "a noise", "c": "a job"}}, {"n": 5, "opts": {"a": "spring", "b": "summer", "c": "winter"}}, {"n": 6, "opts": {"a": "sleep", "b": "wash", "c": "drink"}}, {"n": 7, "opts": {"a": "a cow", "b": "a sheep", "c": "a chicken"}}, {"n": 8, "opts": {"a": "Excuse me", "b": "You’re welcome", "c": "Nice to meet you"}}, {"n": 9, "opts": {"a": "a fork", "b": "chopsticks", "c": "a spoon"}}, {"n": 10, "opts": {"a": "reply", "b": "receive", "c": "contact"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "My sister bought my car last week. I ____ it to her for £5,000."}, {"n": 2, "q": "Leonardo sits at his desk more or ____ all day. He almost never moves."}, {"n": 3, "q": "Japan is a long ____ from England."}, {"n": 4, "q": "He’s not always ____ good health; sometimes he gets very ill."}, {"n": 5, "q": "Who in your family ____ than you goes to church every Sunday?"}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "When Mr Brown enters the room, you must remember to shake ____.", "opts": {"a": "hands", "b": "his hands", "c": "with your hand"}}, {"n": 2, "q": "Would you like ____ a picnic in the park tomorrow?", "opts": {"a": "we eat", "b": "going for", "c": "to have"}}, {"n": 3, "q": "What time did we ____ the school this morning?", "opts": {"a": "get", "b": "fetch", "c": "reach"}}, {"n": 4, "q": "____ two men in the kitchen when we arrived.", "opts": {"a": "They sat", "b": "There were", "c": "Had only"}}, {"n": 5, "q": "Please ____ any of my chips!", "opts": {"a": "don’t eat", "b": "not eating", "c": "you can’t eat"}}, {"n": 6, "q": "The teacher always says “Goodbye” ____ the end of the lesson.", "opts": {"a": "to", "b": "in", "c": "at"}}, {"n": 7, "q": "Why don’t you want to go ____ walk? It’s a beautiful day.", "opts": {"a": "to a", "b": "to do a", "c": "for a"}}, {"n": 8, "q": "My German isn’t good enough for me to ____ a conversation with anybody.", "opts": {"a": "make", "b": "hold", "c": "do"}}, {"n": 9, "q": "I’m very tired now, ____ I want to go to bed.", "opts": {"a": "so", "b": "however", "c": "whilst"}}, {"n": 10, "q": "If you need some new trousers, there’s a good shop near here for ____ clothes.", "opts": {"a": "to buy", "b": "buying", "c": "you can buy"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "I think Tina brought her coat at that new clothes shop in the centre of the town."}, {"n": 2, "text": "I don’t understand why my friend John didn’t message to me when he came to London yesterday."}, {"n": 3, "text": "Paris is one of the biggest city in Europe."}, {"n": 4, "text": "None of us liked Mr Grossman much, but our new physics teacher is worst than him!"}, {"n": 5, "text": "We don’t always go out at the weekend. It depends the weather."}, {"n": 6, "text": "I don’t think anybody apart you loves walking in the rain."}, {"n": 7, "text": "Were the children went in my office this afternoon? I don’t like them going in that room!"}, {"n": 8, "text": "Does anybody know who hang those pictures on our classroom walls? They’re all terrible."}, {"n": 9, "text": "Did Mark arrive to here in his car or did he come by train?"}, {"n": 10, "text": "Go into the living room if you’re cold. There’s nice warm fire in there."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (3,'{"parts": [{"id": "dictation", "points": 15, "text": "Your heart is on the left, but it’s nearer the centre than most people think. She was a great maths teacher, but she taught impolite kids who laughed at her every day. We drove along the road that followed the river. Everything we saw was beautiful. Who drank the vegetable juice? I feel quite weak because I’m very hungry. I ate nothing for breakfast. The boy’s voice quickly got deeper when he became a teenager. My birthday present to my partner last year was a winter coat. He said he loved it, but only wore it twice. I paid for the book, and I read it in one afternoon. If water’s heavier than air, why do clouds stay in the sky?"}, {"id": "oral", "points": 10, "keys": {"1": "b", "2": "a", "3": "c", "4": "b", "5": "a", "6": "c", "7": "c", "8": "a", "9": "c", "10": "b"}, "teacher": {"1": "What’s my job? I wear a uniform and I’m in the army.", "2": "Which month precedes the one before August?", "3": "Which fruit do I like the most? Oranges are the only fruit I prefer to bananas, but I love apples almost as much as both of them.", "4": "Which of these can people make?", "5": "Which is neither the hottest season of the year nor the coldest?", "6": "What do thirsty people need to do?", "7": "What am I? You can see me on a farm; but I’m not generally in a field.", "8": "What do we generally say first when we speak to somebody we don’t know in the street?", "9": "If we want to eat soup, what do we need?", "10": "Which of these verbs is the opposite of “send”?"}}, {"id": "gap", "points": 5, "accept": {"1": ["sold"], "2": ["less"], "3": ["way"], "4": ["in"], "5": ["other"]}}, {"id": "mc", "points": 10, "keys": {"1": "a", "2": "c", "3": "c", "4": "b", "5": "a", "6": "c", "7": "c", "8": "b", "9": "a", "10": "b"}}, {"id": "err", "points": 10, "accept": {"1": ["I think Tina bought her coat at that new clothes shop in the centre of the town."], "2": ["I don’t understand why my friend John didn’t message me when he came to London yesterday."], "3": ["Paris is one of the biggest cities in Europe."], "4": ["None of us liked Mr Grossman much, but our new physics teacher is worse than him!"], "5": ["We don’t always go out at the weekend. It depends on the weather."], "6": ["I don’t think anybody apart from you loves walking in the rain."], "7": ["Were the children in my office this afternoon? I don’t like them going in that room!"], "8": ["Does anybody know who hung those pictures on our classroom walls? They’re all terrible."], "9": ["Did Mark arrive here in his car or did he come by train?"], "10": ["Go into the living room if you’re cold. There’s a nice warm fire in there."]}, "hint": {"1": "Change “brought” to “bought”", "2": "Take out “to” – “message me”", "3": "Change “city” to “cities”", "4": "Change “worst” to “worse”", "5": "Add “on” – “depends on the”", "6": "Add “from” – “apart from you”", "7": "Take out “went” – “children in”", "8": "Change “hang” to “hung”", "9": "Take out “to” – “arrive here”", "10": "Add “a” – “there’s a nice”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (4,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "“Yes, I think we shall.”", "b": "“I would like that.”", "c": "“I have no idea.”"}}, {"n": 2, "opts": {"a": "scissors", "b": "fish", "c": "news"}}, {"n": 3, "opts": {"a": "a bridge", "b": "a field", "c": "a boat"}}, {"n": 4, "opts": {"a": "a zoo", "b": "a museum", "c": "a hotel"}}, {"n": 5, "opts": {"a": "It is difficult for us.", "b": "We think it is boring.", "c": "It is dangerous."}}, {"n": 6, "opts": {"a": "do the shopping", "b": "make the shopping", "c": "go shopping"}}, {"n": 7, "opts": {"a": "pillow", "b": "book", "c": "dirt"}}, {"n": 8, "opts": {"a": "however", "b": "although", "c": "so"}}, {"n": 9, "opts": {"a": "a purse", "b": "a button", "c": "a wallet"}}, {"n": 10, "opts": {"a": "passing an exam", "b": "taking an exam", "c": "doing an exam"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "I thought I was better at tennis than Hannah, but when we played yesterday, she surprised me by ____ almost every game."}, {"n": 2, "q": "Not many people talk about their personal problems ____ public."}, {"n": 3, "q": "Your feet are really small. What ____ shoes do you take?"}, {"n": 4, "q": "My dad got married to my mum at the ____ of forty-nine."}, {"n": 5, "q": "Don’t leave your toys on the floor, Charlie. Please ____ them up and take them to your room."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "I’m going to ____ away this radio. It’s useless.", "opts": {"a": "get", "b": "throw", "c": "pass"}}, {"n": 2, "q": "We can go to Tom’s house for a cup of tea, but we ____ not stay for more than half an hour.", "opts": {"a": "should", "b": "can", "c": "would"}}, {"n": 3, "q": "Don’t you want to taste this drink I made? You don’t ____ to have any, but I think it’s tasty.", "opts": {"a": "like", "b": "try", "c": "have"}}, {"n": 4, "q": "I ____ my mum on my mobile when my little brother cut his finger.", "opts": {"a": "have called", "b": "was calling", "c": "call"}}, {"n": 5, "q": "Sara wanted to go into the water but she ____ to swim, so her mother stopped her.", "opts": {"a": "couldn’t", "b": "wasn’t able", "c": "didn’t know"}}, {"n": 6, "q": "Are you ____ this game boring? I am!", "opts": {"a": "feeling", "b": "making", "c": "finding"}}, {"n": 7, "q": "Does this house belong ____ you? It’s beautiful!", "opts": {"a": "to", "b": "for", "c": "with"}}, {"n": 8, "q": "I’m sorry but I can’t talk now. I’m ____ busy writing that email I told you about.", "opts": {"a": "yet", "b": "always", "c": "still"}}, {"n": 9, "q": "These trousers are £90. I can’t decide if ____ buying.", "opts": {"a": "they’ve value", "b": "it’s a cost of", "c": "they’re worth"}}, {"n": 10, "q": "I’ll see you ____ three weeks’ time.", "opts": {"a": "in", "b": "after", "c": "until"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "I still remember some Latin because I have studied it for four years as a child."}, {"n": 2, "text": "OK, Billy, you can have one more piece of cake, but you must sure you brush your teeth before you go to bed!"}, {"n": 3, "text": "Our kids have a great time if we take them to the zoo. They’ve never been there before."}, {"n": 4, "text": "I know Harry’s always been a good friend of you, but he says some really stupid things sometimes."}, {"n": 5, "text": "My cousin can’t come to our barbecue this Saturday. He’s doctor and has to work all weekend."}, {"n": 6, "text": "Writing that document was hard. It lasted me more than two hours to finish it."}, {"n": 7, "text": "I am full of hope that, in the future, we will succeed finding life on another planet."}, {"n": 8, "text": "Get into bed and go to deep sleep now. Tomorrow’s going to be a busy day."}, {"n": 9, "text": "If it doesn’t cost too much to fly there, we will probably visit to you in the USA next summer."}, {"n": 10, "text": "Everyone can see that James and Sonia love one other very much. I hope they decide to marry one day."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (4,'{"parts": [{"id": "dictation", "points": 15, "text": "The pair of glasses I bought were broken. However, when I returned to the shop, they refused to change them. What’s your colleague’s surname? He won’t tell me. I’m getting dressed to go out now, and I’ll probably return home late. They believed their boss was guilty of a crime. I’m nervous around dogs because they’re often excited and very noisy. However, I’m not afraid of cats; they’re usually calmer and quieter. Smoking cigarettes causes terrible health problems. Have you noticed Dad’s haircut? I doubt he’s happy with that! To speak a foreign language well, one needs to practise a lot. Pour some whisky over this ice. We’re going to go swimming in the lake tonight. Who else is interested?"}, {"id": "oral", "points": 10, "keys": {"1": "b", "2": "c", "3": "a", "4": "c", "5": "a", "6": "b", "7": "b", "8": "c", "9": "b", "10": "a"}, "teacher": {"1": "What’s the best answer to this question: “Shall we go to see a movie next Saturday?”", "2": "Which of these nouns is never plural?", "3": "What am I talking about? I use it to walk across the river at the end of the road where I live.", "4": "When people go on holiday, some of them like to stay at one of these. What am I talking about?", "5": "When we struggle to do something, which of these is always a fact?", "6": "Which expression is not correct English?", "7": "Which of these words can be a verb?", "8": "Which word can mean the same as “therefore”?", "9": "Which of these objects never contains anything?", "10": "Which of these generally makes people happy?"}}, {"id": "gap", "points": 5, "accept": {"1": ["winning"], "2": ["in"], "3": ["size"], "4": ["age"], "5": ["pick"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "a", "3": "c", "4": "b", "5": "b", "6": "c", "7": "a", "8": "c", "9": "c", "10": "a"}}, {"id": "err", "points": 10, "accept": {"1": ["I still remember some Latin because I studied it for four years as a child."], "2": ["OK, Billy, you can have one more piece of cake, but you must make sure you brush your teeth before you go to bed!"], "3": ["Our kids will have a great time if we take them to the zoo. They’ve never been there before."], "4": ["I know Harry’s always been a good friend of yours, but he says some really stupid things sometimes."], "5": ["My cousin can’t come to our barbecue this Saturday. He’s a doctor and has to work all weekend."], "6": ["Writing that document was hard. It took me more than two hours to finish it."], "7": ["I am full of hope that, in the future, we will succeed in finding life on another planet."], "8": ["Get into bed and go to sleep now. Tomorrow’s going to be a busy day."], "9": ["If it doesn’t cost too much to fly there, we will probably visit you in the USA next summer."], "10": ["Everyone can see that James and Sonia love each other very much. I hope they decide to marry one day."]}, "hint": {"1": "Take out “have” – “I studied”", "2": "Add “make” – “must make sure”", "3": "Add “will” – “kids will have”", "4": "Change “you” to “yours” – “of yours, but”", "5": "Add “a” – “He’s a doctor”", "6": "Change “lasted” to “took” – “It took me”", "7": "Add “in” – “succeed in finding”", "8": "Take out “deep” – “to sleep”", "9": "Take out “to” – “visit you”", "10": "Change “one” to “each” – “love each other”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (5,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "after a bath", "b": "at parties", "c": "before travelling"}}, {"n": 2, "opts": {"a": "before 9 p.m.", "b": "at 9 p.m.", "c": "after 9 p.m."}}, {"n": 3, "opts": {"a": "on the hob", "b": "in the oven", "c": "under the grill"}}, {"n": 4, "opts": {"a": "a shower", "b": "exercise", "c": "a complaint"}}, {"n": 5, "opts": {"a": "thunder", "b": "a storm", "c": "lightning"}}, {"n": 6, "opts": {"a": "cotton", "b": "leather", "c": "wool"}}, {"n": 7, "opts": {"a": "a belt", "b": "a chain", "c": "a watch"}}, {"n": 8, "opts": {"a": "should", "b": "may", "c": "will"}}, {"n": 9, "opts": {"a": "soup", "b": "a biscuit", "c": "ham"}}, {"n": 10, "opts": {"a": "“How do you do?”", "b": "“You’re welcome.”", "c": "“Very well, thank you.”"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "Sarah’s only worked here ____ the beginning of the year."}, {"n": 2, "q": "Please, there’s no hurry. ____ your time."}, {"n": 3, "q": "Robert’s flight took ____ about two hours late, so he’s not here yet."}, {"n": 4, "q": "I’m so sorry to ____ you waiting, Madam. I’ll be with you in one minute."}, {"n": 5, "q": "The wedding was lovely. The groom wore a dark suit, and the ____ wore the most beautiful dress I’ve ever seen."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "I can play the piano, but ____ the drums is what I really love.", "opts": {"a": "play", "b": "playing", "c": "to play"}}, {"n": 2, "q": "We ____ our raincoats; it isn’t going to rain much in Spain.", "opts": {"a": "won’t need", "b": "needn’t", "c": "haven’t need"}}, {"n": 3, "q": "They made us ____ inside the hotel until the police said it was OK to leave.", "opts": {"a": "stay", "b": "staying", "c": "to stay"}}, {"n": 4, "q": "You really look ____ your mother when she was your age.", "opts": {"a": "as", "b": "how", "c": "like"}}, {"n": 5, "q": "You don’t have to write this document ____ once. Tomorrow will be fine.", "opts": {"a": "at", "b": "all", "c": "for"}}, {"n": 6, "q": "I get about five weeks’ holiday each year, ____ all the normal public holidays.", "opts": {"a": "as well", "b": "even", "c": "including"}}, {"n": 7, "q": "Her sunglasses are cheap. Mine are ____ more expensive!", "opts": {"a": "so", "b": "much", "c": "very"}}, {"n": 8, "q": "Julia often prefers to avoid work if she can; in other ____, she’s pretty lazy.", "opts": {"a": "ways", "b": "words", "c": "times"}}, {"n": 9, "q": "I think I’m ____ a cold. Do you have any lemon tea?", "opts": {"a": "catching", "b": "suffering", "c": "taking"}}, {"n": 10, "q": "We changed the kitchen, bought new curtains, and painted each bedroom. It all ____ to about £15,000.", "opts": {"a": "added", "b": "amounted", "c": "measured"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "I’m going to speak to Derek when he gets here. He’s being late for work again, and this is the third time this month."}, {"n": 2, "text": "You’d make fewer mistakes if you didn’t always do everything with a hurry."}, {"n": 3, "text": "We thought he was working from home, but then we found it out he was spending most of his time watching films on TV!"}, {"n": 4, "text": "Since I came to work in Paris, I’ve lived my own in a small flat near the centre, and I can’t complain. It’s an amazing city to live in."}, {"n": 5, "text": "It was painful to hear Dina say we had nothing common; I always believed we were really good friends."}, {"n": 6, "text": "He can ride his motorbike on the road if he were two years older, but he’s only fifteen."}, {"n": 7, "text": "All the coaches were plenty of people. We couldn’t let any more passengers get on."}, {"n": 8, "text": "Your pasta is ready to serve, and the salad is prepared for you at the moment."}, {"n": 9, "text": "Despite of his moustache and beard, everyone found it hard to believe Jason was more than eighteen years old."}, {"n": 10, "text": "If you have any questions during your stay at the hotel, please come and talk to myself or any other member of staff."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (5,'{"parts": [{"id": "dictation", "points": 15, "text": "Don’t boil the sauce. Turn the flame down. After retiring, she’ll thoroughly enjoy life; I’m certain. We’ll reach the coast before the sun rises. Standard train fares here are fairly high. A bus is a big vehicle, but usually has only four wheels. Our accommodation was terrible. The bathroom basin was dirty, and the fridge was faulty. London today has been hot, and many visitors are using umbrellas to protect themselves from the sun. The journey across the desert lasted three days. That mirror’s very valuable and it’s exactly the right height for our living room. In this country nowadays, several famous foreign authors sell rather well. Don’t knock. He may be asleep. If prisoners hid in that lorry, they could probably escape."}, {"id": "oral", "points": 10, "keys": {"1": "c", "2": "a", "3": "b", "4": "c", "5": "a", "6": "a", "7": "b", "8": "b", "9": "c", "10": "a"}, "teacher": {"1": "When do people pack?", "2": "I’ll be sleeping at 9 p.m. this evening, so when will I go to sleep?", "3": "When we’re baking something, where is it?", "4": "Which of these can follow the verb “make”?", "5": "What might you suddenly hear during a short period of really bad weather?", "6": "Which of these comes from a plant?", "7": "I sometimes wear this around my neck. What is it?", "8": "When we ask for permission, which of these auxiliary verbs is often used?", "9": "I ate a slice of this with my lunch yesterday. What was it?", "10": "When somebody says “How do you do?”, what’s the usual reply?"}}, {"id": "gap", "points": 5, "accept": {"1": ["since"], "2": ["Take"], "3": ["off"], "4": ["keep"], "5": ["bride"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "a", "3": "a", "4": "c", "5": "a", "6": "c", "7": "b", "8": "b", "9": "a", "10": "b"}}, {"id": "err", "points": 10, "accept": {"1": ["I’m going to speak to Derek when he gets here. He’s late for work again, and this is the third time this month."], "2": ["You’d make fewer mistakes if you didn’t always do everything in a hurry."], "3": ["We thought he was working from home, but then we found out he was spending most of his time watching films on TV!"], "4": ["Since I came to work in Paris, I’ve lived on my own in a small flat near the centre, and I can’t complain. It’s an amazing city to live in."], "5": ["It was painful to hear Dina say we had nothing in common; I always believed we were really good friends."], "6": ["He could ride his motorbike on the road if he were two years older, but he’s only fifteen."], "7": ["All the coaches were full of people. We couldn’t let any more passengers get on."], "8": ["Your pasta is ready to serve, and the salad is being prepared for you at the moment."], "9": ["Despite his moustache and beard, everyone found it hard to believe Jason was more than eighteen years old."], "10": ["If you have any questions during your stay at the hotel, please come and talk to me or any other member of staff."]}, "hint": {"1": "Take out “being” – “He’s late”", "2": "Change “with” to “in” – “everything in a”", "3": "Take out “it” – “found out”", "4": "Add “on” – “lived on my”", "5": "Add “in” – “nothing in common”", "6": "Change “can” to “could” – “He could ride”", "7": "Change “plenty” to “full” – “were full of”", "8": "Add “being” – “is being prepared”", "9": "Take out “of” – “Despite his”", "10": "Change “myself” to “me” – “to me or”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (6,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "take", "b": "manage", "c": "make"}}, {"n": 2, "opts": {"a": "stressed", "b": "stressful", "c": "stressing"}}, {"n": 3, "opts": {"a": "on", "b": "for", "c": "in"}}, {"n": 4, "opts": {"a": "in", "b": "at", "c": "by"}}, {"n": 5, "opts": {"a": "has been having", "b": "is having", "c": "has had"}}, {"n": 6, "opts": {"a": "wasn’t", "b": "hadn’t been", "c": "wouldn’t have"}}, {"n": 7, "opts": {"a": "wavier and wavier", "b": "always wavier", "c": "every time wavier"}}, {"n": 8, "opts": {"a": "Providing", "b": "Whether", "c": "Supposing"}}, {"n": 9, "opts": {"a": "enjoyed", "b": "used", "c": "ought"}}, {"n": 10, "opts": {"a": "had packed", "b": "was packing", "c": "packed"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "Hi Sarah. Could you bring a ____ of wine glasses with you when you come this evening? We’ve only got six, and there’ll be eight of us at dinner."}, {"n": 2, "q": "Dad, I really need the bathroom. ____ me know when it’s free, please."}, {"n": 3, "q": "I’m sorry, but not ____ Paul could find the fault, and he’s usually really good at fixing laptops."}, {"n": 4, "q": "Dave doesn’t like talking about his police work when he’s off ____, so just chat with him about other stuff when he comes this evening, OK?"}, {"n": 5, "q": "I ____ exactly the same as I did when I was twenty: 75 kg."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "I can play the piano, but ____ the drums is what I really love.", "opts": {"a": "play", "b": "playing", "c": "to play"}}, {"n": 2, "q": "We ____ our raincoats; it isn’t going to rain much in Spain.", "opts": {"a": "won’t need", "b": "needn’t", "c": "haven’t need"}}, {"n": 3, "q": "They made us ____ inside the hotel until the police said it was OK to leave.", "opts": {"a": "stay", "b": "staying", "c": "to stay"}}, {"n": 4, "q": "You really look ____ your mother when she was your age.", "opts": {"a": "as", "b": "how", "c": "like"}}, {"n": 5, "q": "You don’t have to write this document ____ once. Tomorrow will be fine.", "opts": {"a": "at", "b": "all", "c": "for"}}, {"n": 6, "q": "I get about five weeks’ holiday each year, ____ all the normal public holidays.", "opts": {"a": "as well", "b": "even", "c": "including"}}, {"n": 7, "q": "Her sunglasses are cheap. Mine are ____ more expensive!", "opts": {"a": "so", "b": "much", "c": "very"}}, {"n": 8, "q": "Julia often prefers to avoid work if she can; in other ____, she’s pretty lazy.", "opts": {"a": "ways", "b": "words", "c": "times"}}, {"n": 9, "q": "I think I’m ____ a cold. Do you have any lemon tea?", "opts": {"a": "catching", "b": "suffering", "c": "taking"}}, {"n": 10, "q": "We changed the kitchen, bought new curtains, and painted each bedroom. It all ____ to about £15,000.", "opts": {"a": "added", "b": "amounted", "c": "measured"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "So far, Sam’s got the highest mark, with ninety-three out from a hundred, but I still have seven more tests to correct."}, {"n": 2, "text": "Calm down, sir. Nothing you’ve told me any sense. Start again from the beginning and tell us exactly what you remember about the crime."}, {"n": 3, "text": "Since we live on the fifth floor, we have the outside of all our windows clean by a window cleaning company."}, {"n": 4, "text": "My parents told me they get me a car for my eighteenth birthday. In fact, they promised, but I got a bicycle instead."}, {"n": 5, "text": "We don’t have enough money to buy a property yet, so we’re renting out a tiny flat and trying to save as much as we can every month."}, {"n": 6, "text": "It’s not the train company’s fault; the train left in time. The problem is that we didn’t get here early enough to catch it!"}, {"n": 7, "text": "You’re going to need a pretty big lorry when you move your house, Romero. I’ve never known anyone with such a huge amount of furniture!"}, {"n": 8, "text": "If Paula agreed to give me Italian lessons in the exchange for me teaching her how to play the guitar, that would be perfect. We could both save money!"}, {"n": 9, "text": "Ana and I have stayed in contact since university and, every now again, we meet for lunch."}, {"n": 10, "text": "Last year, I used my car every day to get to work. I no more do that, though, because my new job is so close to home."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (6,'{"parts": [{"id": "dictation", "points": 15, "text": "What a pity! This cereal’s delicious, but a medium bowl actually contains more sugar than four squares of chocolate. Ghosts aren’t scary if you don’t believe in them. With such a wide variety of dishes on the menu, it’s hard to make a choice. I’m only guessing, but this rough weather could last a fortnight. Please fill in the application form. We all escaped from the burning building, although I hurt myself jumping from a room upstairs. When my parents’ marriage failed, they fought each other in the courts. It was quite nasty. I’d encourage you to bring tissues with you; it’s a sad movie. The sailors repaired the boat and left the island immediately. I’m a little deaf, so please speak clearly."}, {"id": "oral", "points": 10, "keys": {"1": "a", "2": "b", "3": "a", "4": "c", "5": "c", "6": "b", "7": "a", "8": "c", "9": "b", "10": "a"}, "teacher": {"1": "Becoming a good cook isn’t easy, but most people can if they ____ the trouble to learn some basic skills and practise regularly.", "2": "I wouldn’t be a soldier if I found life in the army ____ . I enjoy every second of it!", "3": "Most kids of your age aren’t keen ____ jazz, so I was surprised to hear you are.", "4": "A team of doctors were waiting to operate on the man but, ____ the time the ambulance reached the hospital, he’d died.", "5": "It’s only midday, and Ivan ____ at least five cups of coffee. He doesn’t seem to be able to stop!", "6": "I’d have got the medicine for you if the pharmacy ____ closed. I’ll go back tomorrow morning.", "7": "Your hair is getting ____ as you get older.", "8": "Daily life depends so much on electricity. ____ there suddenly wasn’t any, what would happen?", "9": "At university, I ____ to play sport whenever I could.", "10": "I stopped at Emma’s place on the way to the airport. She ____ already and was outside on the pavement with her suitcase."}}, {"id": "gap", "points": 5, "accept": {"1": ["couple"], "2": ["Let"], "3": ["even"], "4": ["duty"], "5": ["weigh"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "a", "3": "a", "4": "c", "5": "a", "6": "c", "7": "b", "8": "b", "9": "a", "10": "b"}}, {"id": "err", "points": 10, "accept": {"1": ["So far, Sam’s got the highest mark, with ninety-three out of a hundred, but I still have seven more tests to correct."], "2": ["Calm down, sir. Nothing you’ve told me makes any sense. Start again from the beginning and tell us exactly what you remember about the crime."], "3": ["Since we live on the fifth floor, we have the outside of all our windows cleaned by a window cleaning company."], "4": ["My parents told me they would get me a car for my eighteenth birthday. In fact, they promised, but I got a bicycle instead."], "5": ["We don’t have enough money to buy a property yet, so we’re renting a tiny flat and trying to save as much as we can every month."], "6": ["It’s not the train company’s fault; the train left on time. The problem is that we didn’t get here early enough to catch it!"], "7": ["You’re going to need a pretty big lorry when you move house, Romero. I’ve never known anyone with such a huge amount of furniture!"], "8": ["If Paula agreed to give me Italian lessons in exchange for me teaching her how to play the guitar, that would be perfect. We could both save money!"], "9": ["Ana and I have stayed in contact since university and, every now and again, we meet for lunch."], "10": ["Last year, I used my car every day to get to work. I no longer do that, though, because my new job is so close to home."]}, "hint": {"1": "Change “from” to “of” – “out of a”", "2": "Add “makes” – “me makes any”", "3": "Change “clean” to “cleaned” – “windows cleaned by”", "4": "Add “would” – “they would get”", "5": "Take out “out” – “renting a”", "6": "Change “in” to “on” – “left on time”", "7": "Take out “your” – “move house”", "8": "Take out “the” – “in exchange”", "9": "Add “and” – “now and again”", "10": "Change “more” to “longer” – “no longer do”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (7,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "Leo", "b": "Tom", "c": "Sam"}}, {"n": 2, "opts": {"a": "setting an egg", "b": "laying an egg", "c": "bearing an egg"}}, {"n": 3, "opts": {"a": "because", "b": "when", "c": "so that"}}, {"n": 4, "opts": {"a": "impolite", "b": "illegal", "c": "unlikely"}}, {"n": 5, "opts": {"a": "So do I.", "b": "So I know.", "c": "So I’ve heard."}}, {"n": 6, "opts": {"a": "wind", "b": "fire", "c": "water"}}, {"n": 7, "opts": {"a": "lots of", "b": "several", "c": "enough"}}, {"n": 8, "opts": {"a": "Not a matter.", "b": "That’s nothing.", "c": "Don’t mention it."}}, {"n": 9, "opts": {"a": "They’re uninteresting", "b": "They’re unhappy", "c": "They’re unintelligent"}}, {"n": 10, "opts": {"a": "hearing", "b": "smelling", "c": "touching"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "You had ____ pay Pablo the money soon or there’ll be trouble!"}, {"n": 2, "q": "Billy won’t go swimming ____ his twin sister can come too. They do everything together."}, {"n": 3, "q": "I don’t mind housework, but I wish my wife occasionally ____ some."}, {"n": 4, "q": "Never say passwords ____ loud; you never know who’s listening!"}, {"n": 5, "q": "Why do you always hide secrets from me? You ought to ____ let me know about this situation much earlier."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "They just said the next station was Cambridge. But it ____ be Cambridge! We didn’t catch the wrong train, did we?!", "opts": {"a": "mustn’t", "b": "can’t", "c": "oughtn’t"}}, {"n": 2, "q": "What’s the name of the country ____ capital is Santiago?", "opts": {"a": "where", "b": "whose", "c": "which"}}, {"n": 3, "q": "You’ll have to speak a lot louder; your grandmother and I can ____ hear a word you’re saying at the moment.", "opts": {"a": "hardly", "b": "almost", "c": "rarely"}}, {"n": 4, "q": "The only reason I ____ so strongly to getting a pet dog is that we live in such a small flat.", "opts": {"a": "disagree", "b": "object", "c": "oppose"}}, {"n": 5, "q": "Sheila felt happy in Italy ____ first, but she soon began to miss the food from her country.", "opts": {"a": "by", "b": "in", "c": "at"}}, {"n": 6, "q": "Even in modern society, ____ old are usually cared for by younger family members.", "opts": {"a": "the", "b": "their", "c": "those"}}, {"n": 7, "q": "The continuing strong winds make the sailing races ____ today.", "opts": {"a": "be exciting", "b": "unusually quickly", "c": "more likely to happen"}}, {"n": 8, "q": "John misses his friends in London. I think he regrets ____ to the countryside.", "opts": {"a": "to move", "b": "moving", "c": "he moved"}}, {"n": 9, "q": "George says he’s the boss, but I know his mother actually ____ the business.", "opts": {"a": "runs", "b": "turns", "c": "stands"}}, {"n": 10, "q": "Ben’s joining the air force because he’s fed ____ with his job and wants more adventure.", "opts": {"a": "down", "b": "over", "c": "up"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "Governments in many countries will have a huge issue with unemployment when computers will become powerful and intelligent enough to do most office jobs."}, {"n": 2, "text": "Maths interests me and is one of my favourite subjects, but was easier for all of us in my class to understand difficult mathematical ideas when Mrs White taught us; she explains things so clearly."}, {"n": 3, "text": "This place was advertised as a family hotel, so I’m surprised by the lacking of activities they offer for kids."}, {"n": 4, "text": "Jurgen Cramer always remains positive. Even though his team loses this next match, I’m certain he’ll have a smile on his face afterwards when he talks to the press."}, {"n": 5, "text": "When I joined the gym, I found it so hard to get up early to go there, but I eventually used to doing that, and now it’s just a habit."}, {"n": 6, "text": "Do you think the new neighbours are the kind of family that we’re going to be able to get along with them well?"}, {"n": 7, "text": "That dress you’ve got on is beautiful. There’s one thing I’d change, though, and that’s those earrings, that look rather heavy, as if they’re pulling your ears down!"}, {"n": 8, "text": "I don’t enjoy at all parties, especially ones like this where I don’t know anyone, so please don’t leave me on my own."}, {"n": 9, "text": "Although flights aren’t cheap, the vacation could end being pretty good value for money, mainly because food and drink prices are so low in that part of the world."}, {"n": 10, "text": "Excuse me. Libraries should be quiet places, but that woman keeps coughing. It’s really getting my nerves, so could you say something to her, please?"}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (7,'{"parts": [{"id": "dictation", "points": 15, "text": "Throughout every speech, her eyes were fierce and bright. She would never give up the dream of being elected. I wonder where everyone is. There must be a problem with public transport. I can only advise you to accept the facts; they’ve run out of money, and are closing the bar permanently. My knowledge of racehorses is extremely limited, but this is definitely a gorgeous animal. I couldn’t care less if some fans claim we’ve let them down. On the whole, I’m proud of what our club’s achieving. As a direct consequence of the owner’s behaviour online, the company was about to lose a great deal of its value. Lawyers everywhere were trying to control the damage. Liquids adopt the shape of the container they’re in."}, {"id": "oral", "points": 10, "keys": {"1": "a", "2": "b", "3": "b", "4": "b", "5": "c", "6": "c", "7": "b", "8": "c", "9": "a", "10": "a"}, "teacher": {"1": "I know three facts: Leo has quite a few friends in London, Tom has few friends in London, and Sam has a few friends in London. Who has the most friends in London?", "2": "What do we say a chicken is doing when it is producing an egg?", "3": "What does the word “once” mean in the sentence “I want to commence my studies once I have all the information I need”?", "4": "In front of which of these adjectives does the word “quite” mean “completely”?", "5": "Which of these is a possible reply to the statement “I don’t like flying”?", "6": "In a flood, what are people surrounded by?", "7": "Which of these cannot come before the word “stuff”?", "8": "When someone thanks us for our help, what can we say?", "9": "If we describe someone as dull, what do we mean?", "10": "Which of these is the name of one of the five senses?"}}, {"id": "gap", "points": 5, "accept": {"1": ["better"], "2": ["unless"], "3": ["did"], "4": ["out"], "5": ["have"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "b", "3": "a", "4": "b", "5": "c", "6": "a", "7": "c", "8": "b", "9": "a", "10": "c"}}, {"id": "err", "points": 10, "accept": {"1": ["Governments in many countries will have a huge issue with unemployment when computers become powerful and intelligent enough to do most office jobs."], "2": ["Maths interests me and is one of my favourite subjects, but it was easier for all of us in my class to understand difficult mathematical ideas when Mrs White taught us; she explains things so clearly."], "3": ["This place was advertised as a family hotel, so I’m surprised by the lack of activities they offer for kids."], "4": ["Jurgen Cramer always remains positive. Even if his team loses this next match, I’m certain he’ll have a smile on his face afterwards when he talks to the press."], "5": ["When I joined the gym, I found it so hard to get up early to go there, but I eventually got used to doing that, and now it’s just a habit."], "6": ["Do you think the new neighbours are the kind of family that we’re going to be able to get along with well?"], "7": ["That dress you’ve got on is beautiful. There’s one thing I’d change, though, and that’s those earrings, which look rather heavy, as if they’re pulling your ears down!"], "8": ["I don’t enjoy all parties, especially ones like this where I don’t know anyone, so please don’t leave me on my own."], "9": ["Although flights aren’t cheap, the vacation could end up being pretty good value for money, mainly because food and drink prices are so low in that part of the world."], "10": ["Excuse me. Libraries should be quiet places, but that woman keeps coughing. It’s really getting on my nerves, so could you say something to her, please?"]}, "hint": {"1": "Take out “will” – “computers become”", "2": "Add “it” – “but it was”", "3": "Change “lacking” to “lack” – “the lack of”", "4": "Change “though” to “if” – “Even if his”", "5": "Add “got” – “eventually got used”", "6": "Take out “them” – “with well”", "7": "Change “that” to “which” – “earrings, which look”", "8": "Take out “at” – “enjoy all”", "9": "Add “up” – “end up being”", "10": "Add “on” – “getting on my”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (8,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "Yours faithfully", "b": "Kind regards", "c": "Yours sincerely"}}, {"n": 2, "opts": {"a": "wasps", "b": "spiders", "c": "bees"}}, {"n": 3, "opts": {"a": "win it", "b": "fix it", "c": "find it"}}, {"n": 4, "opts": {"a": "soccer", "b": "tennis", "c": "golf"}}, {"n": 5, "opts": {"a": "loaf", "b": "chef", "c": "shelf"}}, {"n": 6, "opts": {"a": "what they enjoy doing", "b": "what they’re talking about", "c": "what job they do"}}, {"n": 7, "opts": {"a": "a bat", "b": "a bird", "c": "a worm"}}, {"n": 8, "opts": {"a": "deer", "b": "cattle", "c": "sheep"}}, {"n": 9, "opts": {"a": "a quarrel", "b": "an argument", "c": "a discussion"}}, {"n": 10, "opts": {"a": "doctor", "b": "farmer", "c": "hairdresser"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "I’d forgotten to ____ the coffee, so all the sugar was just sitting at the bottom of the cup."}, {"n": 2, "q": "Shaun kept asking personal questions, so Emma told him to ____ his own business."}, {"n": 3, "q": "A big breakfast’s ____ the job before a long country walk. You need the energy!"}, {"n": 4, "q": "Shall we go out tonight, or ____ you rather stay at home?"}, {"n": 5, "q": "I’ve no idea where the hospital is, but Mike ____ bound to know."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "My grandmother’s job involved ____ to many different countries to work with the best scientists in the world.", "opts": {"a": "with journeys", "b": "travelling", "c": "that she flew"}}, {"n": 2, "q": "Avoiding certain types of food can ____ a very positive effect on your health.", "opts": {"a": "make", "b": "have", "c": "do"}}, {"n": 3, "q": "We should ____ to every word Doctor Khan says; he’s an expert on this type of operation.", "opts": {"a": "trust", "b": "concentrate", "c": "attend"}}, {"n": 4, "q": "You ____ read the whole book. Mr Thompson said the test would only be on the first chapter, so you’ve wasted your time.", "opts": {"a": "needn’t have", "b": "needn’t", "c": "hadn’t need to"}}, {"n": 5, "q": "We didn’t cut ____; we had to make sure we did everything properly.", "opts": {"a": "turnings", "b": "bends", "c": "corners"}}, {"n": 6, "q": "Mum said Jake was my cousin, but, ____ to Dad, that’s not actually the case.", "opts": {"a": "relating", "b": "according", "c": "second"}}, {"n": 7, "q": "As children, my sister and I always said ____ before going to bed. We’re from a very religious family.", "opts": {"a": "prayers", "b": "praise", "c": "prays"}}, {"n": 8, "q": "Mandy’s coming to the bar with us, but not to the party ____.", "opts": {"a": "eventually", "b": "following", "c": "afterwards"}}, {"n": 9, "q": "Eric was bored, and he decided he needed to take ____ a hobby.", "opts": {"a": "up", "b": "to", "c": "in"}}, {"n": 10, "q": "____ time, let’s use the microwave instead of the normal oven.", "opts": {"a": "As for saving", "b": "So as to save", "c": "In order we save"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "Tourists are advised to watch step when they visit this region of the country, since the level of crime is higher than in the east."}, {"n": 2, "text": "People generally seem very willing to judge Ethan for his crimes, but they never pull into account the awful experiences he suffered during his childhood."}, {"n": 3, "text": "On the average, adults in the UK take between three and four thousand steps per day."}, {"n": 4, "text": "The couple had saved more than they had originally thought was possible, but they still did not afford to travel around Asia during the summer."}, {"n": 5, "text": "Everything Mr Everett explains during his maths lessons goes in one ear and out other because he’s got such a dull voice."}, {"n": 6, "text": "I’m concerned that the builders will not have replaced all the floorboards in the dining room by the time the next-door neighbours will come round for lunch."}, {"n": 7, "text": "There was little laughter due the fact that the show was not at all amusing."}, {"n": 8, "text": "Boris cut his thumb almost as soon as he picked up the knife; he has only been holding it for ten seconds or so!"}, {"n": 9, "text": "If your dad had never moved to USA, we would never have met, and neither you nor your elder brother would ever have been born. Isn’t that amazing?"}, {"n": 10, "text": "My colleagues’ opinions on how they should settle the matter differed from greatly, and the conversation soon became unpleasant."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (8,'{"parts": [{"id": "dictation", "points": 15, "text": "It’d be sensible to start the reception fairly soon after the ceremony. If the referee had been a real professional, he wouldn’t have spoilt the match by interfering when it was totally unnecessary. I wasn’t injured, but I did swear briefly when the edge of the hammer hit my fingernail. You can’t deny he’s an evil man. I have no sympathy for him. Who were your childhood heroes? It’s only idiots who ignore the dangers to the environment. Comb your hair. It’s looking a bit weird. With tears in their eyes after hugging their niece, they immediately told the surgeon how grateful they were. Masses of railway workers are about to go on strike, and nobody’s available to replace them."}, {"id": "oral", "points": 10, "keys": {"1": "a", "2": "c", "3": "c", "4": "a", "5": "b", "6": "b", "7": "c", "8": "b", "9": "a", "10": "b"}, "teacher": {"1": "When we know the name of the person we’re writing to, which ending should we avoid using in an email or letter?", "2": "Without which of these would the world lack honey?", "3": "When we hunt for something, what do we hope to do?", "4": "Which of these sports involves the use of a whistle?", "5": "The plural of only one of these nouns is formed just by adding the letter “s”. Which is it?", "6": "If I say I don’t know what someone’s on about, what don’t I know?", "7": "Which of these possesses no limbs?", "8": "Which of these always refers to more than one animal?", "9": "Which of these is normally the most unpleasant for those involved?", "10": "You hear someone say “The crop’s improving”. What’s their likely occupation?"}}, {"id": "gap", "points": 5, "accept": {"1": ["stir"], "2": ["mind"], "3": ["just"], "4": ["would"], "5": ["is"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "b", "3": "c", "4": "a", "5": "c", "6": "b", "7": "a", "8": "c", "9": "a", "10": "b"}}, {"id": "err", "points": 10, "accept": {"1": ["Tourists are advised to watch their step when they visit this region of the country, since the level of crime is higher than in the east."], "2": ["People generally seem very willing to judge Ethan for his crimes, but they never take into account the awful experiences he suffered during his childhood."], "3": ["On average, adults in the UK take between three and four thousand steps per day."], "4": ["The couple had saved more than they had originally thought was possible, but they still could not afford to travel around Asia during the summer."], "5": ["Everything Mr Everett explains during his maths lessons goes in one ear and out the other because he’s got such a dull voice."], "6": ["I’m concerned that the builders will not have replaced all the floorboards in the dining room by the time the next-door neighbours come round for lunch."], "7": ["There was little laughter due to the fact that the show was not at all amusing."], "8": ["Boris cut his thumb almost as soon as he picked up the knife; he had only been holding it for ten seconds or so!"], "9": ["If your dad had never moved to the USA, we would never have met, and neither you nor your elder brother would ever have been born. Isn’t that amazing?"], "10": ["My colleagues’ opinions on how they should settle the matter differed greatly, and the conversation soon became unpleasant."]}, "hint": {"1": "Add “their” – “watch their step”", "2": "Change “pull” to “take” – “never take into”", "3": "Take out “the” – “On average”", "4": "Change “did” to “could” – “still could not”", "5": "Add “the” – “out the other”", "6": "Take out “will” – “neighbours come”", "7": "Add “to” – “due to the”", "8": "Change “has” to “had” – “he had only”", "9": "Add “the” – “to the USA”", "10": "Take out “from” – “differed greatly”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (9,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "relieved", "b": "annoyed", "c": "curious"}}, {"n": 2, "opts": {"a": "grapes", "b": "strawberries", "c": "plums"}}, {"n": 3, "opts": {"a": "a belt", "b": "a door", "c": "a meal"}}, {"n": 4, "opts": {"a": "he’d sing", "b": "he sang", "c": "he’s sung"}}, {"n": 5, "opts": {"a": "when they’re dancing", "b": "when they’re frightened", "c": "when they’re at work"}}, {"n": 6, "opts": {"a": "a five-hours trip", "b": "a bad-made jacket", "c": "a green-eyed girl"}}, {"n": 7, "opts": {"a": "eyebrows", "b": "eyelashes", "c": "eyelids"}}, {"n": 8, "opts": {"a": "from now on", "b": "despite this", "c": "therefore"}}, {"n": 9, "opts": {"a": "the English", "b": "the German", "c": "the Chinese"}}, {"n": 10, "opts": {"a": "carefully", "b": "eagerly", "c": "angrily"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "Australia’s such an interesting country, Sue. If ____ you’d come too!"}, {"n": 2, "q": "They said goodbye with tears in their eyes, not knowing that they ____, in fact, to meet again in London after the war."}, {"n": 3, "q": "Come on, Jorge! The faster you walk, the ____ likely it is you’ll miss your train."}, {"n": 4, "q": "The woman who owns these paintings has no idea about art. She’s actually hung one of them ____ down!"}, {"n": 5, "q": "When a tortoise feels it is in danger, it pulls its head back inside its ____."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "I’m so tired. I just came out of a ____ interview for a new position at work.", "opts": {"a": "three-hour", "b": "three-houred", "c": "three-hours’"}}, {"n": 2, "q": "You just can’t help ____ when you hear that song, can you?!", "opts": {"a": "to dance", "b": "dancing", "c": "except dance"}}, {"n": 3, "q": "The monkey population in this jungle has ____ by more than 40% in the last three years.", "opts": {"a": "decreased", "b": "cut down", "c": "settled"}}, {"n": 4, "q": "These tiny creatures are ____ to the largely empty desert landscape of the south.", "opts": {"a": "singular", "b": "individual", "c": "peculiar"}}, {"n": 5, "q": "Let’s not involve Adam now. I ____ he’d have some interesting thoughts, but it’s far too late to change plans.", "opts": {"a": "dare to say", "b": "dare say", "c": "dare saying"}}, {"n": 6, "q": "Performing at a charity event that Eddy Town, owner of Q22 Music, happened to be at was the lucky ____ Tom had been hoping for.", "opts": {"a": "kick", "b": "shot", "c": "break"}}, {"n": 7, "q": "In my opinion, going to a pub would be preferable ____ sitting in a restaurant. It’d feel less formal.", "opts": {"a": "than", "b": "to", "c": "before"}}, {"n": 8, "q": "____ my point of view, there was never any chance we could win that match. The other team were just too strong.", "opts": {"a": "From", "b": "In", "c": "With"}}, {"n": 9, "q": "Tomorrow, I’ll tell the board I’m quitting. That’ll take them all ____ surprise!", "opts": {"a": "in", "b": "with", "c": "by"}}, {"n": 10, "q": "OK, the dogs can stay here while we eat, but if they start to make a nuisance ____ themselves, they’ll have to leave.", "opts": {"a": "by", "b": "with", "c": "of"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "Excuse me, but I don’t think my relationship problems with Carolina have anything to do you, so I’d be grateful if you’d mind your own business."}, {"n": 2, "text": "For any professional classical musician, practising each other day is not at all sufficient, as far as I’m concerned."}, {"n": 3, "text": "The extreme temperatures on the coast hardly effect me at all on account of the fact that, since I grew up in India, my body’s naturally accustomed to hot weather."}, {"n": 4, "text": "The cost of getting this guitar repaired is likely to be somewhat high. If you ask me, you might well buy a new one; I’ve seen some real bargains online recently."}, {"n": 5, "text": "If I hadn’t persuaded you to have a strong coffee beforehand, I’m absolutely certain you would have fallen to asleep within a few minutes of the start of the play."}, {"n": 6, "text": "By the end of this month, they have been building the new stadium for exactly three years; it’s taking forever, and has cost twice as much as anyone had predicted."}, {"n": 7, "text": "When certain fruits, especially strawberries, are in their season, I tend to spend hours in the kitchen making tasty desserts that can be frozen for use later on."}, {"n": 8, "text": "Emily was rather weird at the dinner party. She needs to learn to control her jealousy. Unless, I doubt Mark’s going to keep going out with her much longer."}, {"n": 9, "text": "Wow, I’ve never seen you sweating so much and out of your breath like that, Terry! Have you been running or something? Sit down for a moment or two and relax."}, {"n": 10, "text": "My mum’s known for losing her temper, but she’s harmless in relation with her sister, Aunt May. She makes no effort at all to hide her emotions when she’s angry."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (9,'{"parts": [{"id": "dictation", "points": 15, "text": "You can’t sew without a needle and thread. People seldom give speeches completely off the cuff. It requires loads of confidence. He only made one remark: that your version of events proved you were a liar. We can’t make up our minds whether to get a kitten or a puppy. I reckon the thief that robbed me also stole your bike. At the gym, I wipe sweat from my forehead with a small towel. I need a screwdriver to screw this handle to the cupboard. The knife slipped slightly, cutting my thumb, but it healed fast. Our teacher warned us we’d be punished if we got caught wandering around at night. Stop staring at me; it’s making me anxious."}, {"id": "oral", "points": 10, "keys": {"1": "b", "2": "a", "3": "a", "4": "c", "5": "b", "6": "c", "7": "b", "8": "c", "9": "b", "10": "a"}, "teacher": {"1": "How am I probably feeling if I describe something that’s just happened as “the last straw”?", "2": "I bought a bunch of these yesterday. What did I buy?", "3": "Which of these can we fasten?", "4": "If you put this phrase immediately after the words “I wish”, it’d be grammatically wrong. Which phrase am I talking about?", "5": "When might a group of people scatter?", "6": "Only one of these is correct in English. Which is it?", "7": "We each have quite a few of these. What am I referring to?", "8": "Which of these is the word “thus” similar in meaning to?", "9": "Which phrase cannot be used to mean people in general of that nationality?", "10": "How do we act when we’re being cautious?"}}, {"id": "gap", "points": 5, "accept": {"1": ["only"], "2": ["were"], "3": ["less"], "4": ["upside"], "5": ["shell"]}}, {"id": "mc", "points": 10, "keys": {"1": "a", "2": "b", "3": "a", "4": "c", "5": "b", "6": "c", "7": "b", "8": "a", "9": "c", "10": "c"}}, {"id": "err", "points": 10, "accept": {"1": ["Excuse me, but I don’t think my relationship problems with Carolina have anything to do with you, so I’d be grateful if you’d mind your own business."], "2": ["For any professional classical musician, practising every other day is not at all sufficient, as far as I’m concerned."], "3": ["The extreme temperatures on the coast hardly affect me at all on account of the fact that, since I grew up in India, my body’s naturally accustomed to hot weather."], "4": ["The cost of getting this guitar repaired is likely to be somewhat high. If you ask me, you might as well buy a new one; I’ve seen some real bargains online recently."], "5": ["If I hadn’t persuaded you to have a strong coffee beforehand, I’m absolutely certain you would have fallen asleep within a few minutes of the start of the play."], "6": ["By the end of this month, they will have been building the new stadium for exactly three years; it’s taking forever, and has cost twice as much as anyone had predicted."], "7": ["When certain fruits, especially strawberries, are in season, I tend to spend hours in the kitchen making tasty desserts that can be frozen for use later on."], "8": ["Emily was rather weird at the dinner party. She needs to learn to control her jealousy. Otherwise, I doubt Mark’s going to keep going out with her much longer."], "9": ["Wow, I’ve never seen you sweating so much and out of breath like that, Terry! Have you been running or something? Sit down for a moment or two and relax."], "10": ["My mum’s known for losing her temper, but she’s harmless in relation to her sister, Aunt May. She makes no effort at all to hide her emotions when she’s angry."]}, "hint": {"1": "Add “with” – “do with you”", "2": "Change “each” to “every” – “practising every other”", "3": "Change “effect” to “affect” – “hardly affect me”", "4": "Add “as” – “might as well”", "5": "Take out “to” – “fallen asleep”", "6": "Add “will” – “they will have”", "7": "Take out “their” – “in season”", "8": "Change “Unless” to “Otherwise” – “jealousy. Otherwise, I”", "9": "Take out “your” – “of breath”", "10": "Change “with” to “to” – “relation to her”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (10,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "walking", "b": "eating", "c": "writing"}}, {"n": 2, "opts": {"a": "a tent", "b": "a torch", "c": "a towel"}}, {"n": 3, "opts": {"a": "She can be annoying.", "b": "She talks very quickly.", "c": "She lacks confidence."}}, {"n": 4, "opts": {"a": "grapes", "b": "shoes", "c": "plants"}}, {"n": 5, "opts": {"a": "experiencing a sense of shame", "b": "being outside in freezing temperatures", "c": "receiving unexpected news"}}, {"n": 6, "opts": {"a": "around her wrist", "b": "in her kitchen", "c": "on her bicycle"}}, {"n": 7, "opts": {"a": "financial advice", "b": "time away from work", "c": "medical attention"}}, {"n": 8, "opts": {"a": "when they’re sleeping", "b": "when they’re eating", "c": "when they’re running"}}, {"n": 9, "opts": {"a": "We’ll cut down ...", "b": "They are coping ...", "c": "I helped myself ..."}}, {"n": 10, "opts": {"a": "a bucket", "b": "a blanket", "c": "a broom"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "I reckon it’s ____ you repaid your loans, Brian. Your borrowing is out of control."}, {"n": 2, "q": "As a teenager, I ____ rarely listen to anything my parents told me."}, {"n": 3, "q": "Maribel’s not ____ of cats. In fact, they make her feel very nervous."}, {"n": 4, "q": "This shirt was dark green when I bought it, but it’s ____ a little each time I’ve washed it; now it’s pale green."}, {"n": 5, "q": "When her opponent hit the ball into the net, Aryna ____ into tears of relief and joy. Finally, she was a champion!"}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "I’ll call my parents tomorrow; ____ bothered to do that now.", "opts": {"a": "I’m not", "b": "I can’t be", "c": "I haven’t"}}, {"n": 2, "q": "Why did you discourage ____ theatre? Acting was my dream.", "opts": {"a": "that I studied", "b": "me from studying", "c": "me to study"}}, {"n": 3, "q": "Are you familiar ____ Japanese cuisine? It’s very healthy, and delicious too!", "opts": {"a": "about", "b": "to", "c": "with"}}, {"n": 4, "q": "Why do you bother ____ your aunt every week if you can’t stand her?", "opts": {"a": "for visiting", "b": "and visit", "c": "to visit"}}, {"n": 5, "q": "While you’re staying with us in Spain, you have to ____ advantage of the location to visit some of the pretty towns on the coast.", "opts": {"a": "make", "b": "use", "c": "take"}}, {"n": 6, "q": "Of all the planets near ours, Jupiter is the largest ____ far.", "opts": {"a": "so", "b": "by", "c": "though"}}, {"n": 7, "q": "How can you possibly ____ anyone for this? It was obviously just an accident.", "opts": {"a": "blame", "b": "accuse", "c": "suspect"}}, {"n": 8, "q": "Sam wouldn’t currently be wasting his life in prison if ____ to my advice at the time.", "opts": {"a": "he’d listened", "b": "he’d have listened", "c": "he listened"}}, {"n": 9, "q": "These rooms are out of ____ to anyone who is not a member of the palace staff.", "opts": {"a": "bounds", "b": "limits", "c": "entry"}}, {"n": 10, "q": "The head teacher disapproved ____ my hair, and I was sent home to change the colour.", "opts": {"a": "for", "b": "against", "c": "of"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "It’s hardly fair to expect Carla to keep her room neat and tidy without help from one of us. Despite how grown-up we think she is, we have to make allowances her age; she’s only just six!"}, {"n": 2, "text": "I seem to have little luck as regards my choices of books to buy. It really is such a long time since I have felt totally absorbed in a great novel."}, {"n": 3, "text": "Top professional ballet dancers are known they practise at least five days each week for a minimum of seven hours."}, {"n": 4, "text": "I wish we had remembered to invite all the neighbours. I reckon there would have been at least a dozen of more people at the barbecue if we had, and we probably wouldn’t have received any complaints about noise."}, {"n": 5, "text": "My neck feels really uncomfortable this morning; I can hardly turn it. I must lain in an odd position, or maybe it’s those new pillows you insisted on buying."}, {"n": 6, "text": "The local population have been putting lots of pressure on the police to explain why they are unwilling to investigate to why this town is so badly affected by the crime of shoplifting."}, {"n": 7, "text": "I was informed I would need to wait over an hour to be treated by a doctor, so I decided to make the best of the situation in the meanwhile, took out my eBook, and tried to ignore the pain as much as possible."}, {"n": 8, "text": "Although Sam is Scottish in birth, he’s only ever travelled up there once as an adult, and that was for a wedding."}, {"n": 9, "text": "We spent ages discussing whether we could afford to spend so much on a work of art, so you can imagine how disappointed we felt when it turned to be just a reproduction. As the price was so high, we’d thought we were buying the original painting."}, {"n": 10, "text": "Do you think my sister and I sound alike ourselves on the phone? Quite a few people have claimed they have trouble distinguishing our voices."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (10,'{"parts": [{"id": "dictation", "points": 15, "text": "The venue’s extraordinary, the scenery was really striking, and your acting was magnificent. So cheer up! That critic’s talking nonsense. The play didn’t drag at all. You heard the roar of the applause. Forgive me, but could you use this saucer to prevent your cup from staining the dining table? I tied a double knot in the rope, just to be on the safe side. Our chief aim is to prevent disease from spreading as a result of humans consuming raw or rotten meat. Admission to the gallery isn’t free. Don’t whisper while she’s talking. It’s very rude indeed! Your refusal to move that van is causing a traffic jam; the situation’s getting extremely awkward. The contents of my wooden chest are immensely precious."}, {"id": "oral", "points": 10, "keys": {"1": "b", "2": "c", "3": "a", "4": "a", "5": "b", "6": "c", "7": "c", "8": "a", "9": "a", "10": "c"}, "teacher": {"1": "My jaw hurts at the moment, so which action might be uncomfortable for me?", "2": "If it was damp once I’d used it, what is it likely to have been?", "3": "When someone says “My sister’s hard to put up with”, which statement about the sister is most likely to be true?", "4": "They were sour last week, but now they’re ripe. What am I referring to?", "5": "Which tends to cause people to shiver?", "6": "Serena’s very happy with her new saddle. Where will she put it?", "7": "What would someone benefit from if they were choking badly?", "8": "When might someone snore?", "9": "Which of these would you expect to be followed by the word “on”?", "10": "I can see my dad’s busy sweeping. What’s he holding?"}}, {"id": "gap", "points": 5, "accept": {"1": ["time"], "2": ["would"], "3": ["fond"], "4": ["faded"], "5": ["burst"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "b", "3": "c", "4": "c", "5": "c", "6": "b", "7": "a", "8": "a", "9": "a", "10": "c"}}, {"id": "err", "points": 10, "accept": {"1": ["It’s hardly fair to expect Carla to keep her room neat and tidy without help from one of us. Despite how grown-up we think she is, we have to make allowances for her age; she’s only just six!"], "2": ["I seem to have little luck as regards my choices of books to buy. It really is such a long time since I felt totally absorbed in a great novel."], "3": ["Top professional ballet dancers are known to practise at least five days each week for a minimum of seven hours."], "4": ["I wish we had remembered to invite all the neighbours. I reckon there would have been at least a dozen more people at the barbecue if we had, and we probably wouldn’t have received any complaints about noise."], "5": ["My neck feels really uncomfortable this morning; I can hardly turn it. I must have lain in an odd position, or maybe it’s those new pillows you insisted on buying."], "6": ["The local population have been putting lots of pressure on the police to explain why they are unwilling to investigate why this town is so badly affected by the crime of shoplifting."], "7": ["I was informed I would need to wait over an hour to be treated by a doctor, so I decided to make the best of the situation in the meantime, took out my eBook, and tried to ignore the pain as much as possible."], "8": ["Although Sam is Scottish by birth, he’s only ever travelled up there once as an adult, and that was for a wedding."], "9": ["We spent ages discussing whether we could afford to spend so much on a work of art, so you can imagine how disappointed we felt when it turned out to be just a reproduction. As the price was so high, we’d thought we were buying the original painting."], "10": ["Do you think my sister and I sound alike on the phone? Quite a few people have claimed they have trouble distinguishing our voices."]}, "hint": {"1": "Add “for” – “allowances for her”", "2": "Take out “have” – “I felt”", "3": "Change “they” to “to” – “known to practise”", "4": "Take out “of” – “dozen more”", "5": "Add “have” – “must have lain”", "6": "Take out “to” – “investigate why”", "7": "Change “meanwhile” to “meantime” – “the meantime, took”", "8": "Change “in” to “by” – “Scottish by birth”", "9": "Add “out” – “turned out to”", "10": "Take out “ourselves” – “alike on”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (11,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "changing their opinions", "b": "accepting responsibility", "c": "showing their emotions"}}, {"n": 2, "opts": {"a": "He was punched.", "b": "He went shopping.", "c": "He had a haircut."}}, {"n": 3, "opts": {"a": "involving the police", "b": "pretending you’re not bothered", "c": "expressing thanks"}}, {"n": 4, "opts": {"a": "your garden", "b": "your local grocer’s", "c": "your workplace"}}, {"n": 5, "opts": {"a": "a get-together", "b": "an exercise routine", "c": "a new product"}}, {"n": 6, "opts": {"a": "inside our mouths", "b": "on our hands", "c": "above our eyes"}}, {"n": 7, "opts": {"a": "swallowing", "b": "yawning", "c": "winking"}}, {"n": 8, "opts": {"a": "losing people’s trust", "b": "missing opportunities", "c": "experiencing stress"}}, {"n": 9, "opts": {"a": "a glimpse", "b": "a gasp", "c": "a glow"}}, {"n": 10, "opts": {"a": "Being near water relaxes her.", "b": "She owns loads of tools.", "c": "Her children love playing outside."}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "No sooner had the dentist’s painkillers ____ off than my lower jaw began aching again."}, {"n": 2, "q": "With violent storms approaching, any attempt to descend the mountain tonight is clearly out of the ____."}, {"n": 3, "q": "How ____ the board are no longer considering the scheme? They seemed so positive last month."}, {"n": 4, "q": "I’m not sure it’s ____ our while travelling all the way to London just for two days."}, {"n": 5, "q": "Could you possibly give me a ____ to the airport next Sunday?"}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "Don’t worry, Mum. I can assure you ____ home on time.", "opts": {"a": "to get", "b": "you’ll get", "c": "getting"}}, {"n": 2, "q": "Just walk up to her and ask her. I don’t know why you keep ____ it off.", "opts": {"a": "laying", "b": "putting", "c": "setting"}}, {"n": 3, "q": "Andy’s always ____ up to you, you know. It was your guitar playing that inspired him to start learning the instrument, and now he’s a professional musician.", "opts": {"a": "taken", "b": "caught", "c": "looked"}}, {"n": 4, "q": "____ they know, but their band is about to become very famous.", "opts": {"a": "Whether or not", "b": "Only", "c": "Little do"}}, {"n": 5, "q": "Jacob will ensure ____ out the barbecue properly, Dad. Don’t worry.", "opts": {"a": "he’s put", "b": "putting", "c": "to put"}}, {"n": 6, "q": "The whole cast performed very well, didn’t they? Needless ____, Tomoko’s voice was incredible as always; she’s so talented!", "opts": {"a": "we say", "b": "said", "c": "to say"}}, {"n": 7, "q": "Usually, Joe just shows ____ when he plays the guitar. He wants everyone to be amazed by his great technique, but what he plays isn’t pleasant to listen to.", "opts": {"a": "off", "b": "up", "c": "out"}}, {"n": 8, "q": "The firm had serious problems last year, but we’ve managed to recover without making even one member of staff ____.", "opts": {"a": "sacked", "b": "redundant", "c": "fired"}}, {"n": 9, "q": "Entertainment for hotel guests is normally organized on a daily ____.", "opts": {"a": "routine", "b": "basis", "c": "request"}}, {"n": 10, "q": "The school has decided to close today ____ light of current weather forecasts.", "opts": {"a": "in", "b": "under", "c": "with"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "I really sympathize with Alan. If you hadn’t all burst out in laughing when he started dancing, he wouldn’t have got so embarrassed and might well have enjoyed the party. It’s such a shame. You know how socially awkward he is."}, {"n": 2, "text": "I had never been expected to work around the clock such a lot prior to be recruited by this firm, but, by and large, I’m not complaining."}, {"n": 3, "text": "A jigsaw puzzle is comprised numerous small, normally wooden or cardboard pieces of various shapes which, once fitted together in the correct manner, form one large picture."}, {"n": 4, "text": "I assumed we would be in serious trouble now, as today is the deadline for paying off our debt. As happens, however, Derek has private funds available and has granted us permission to access them temporarily."}, {"n": 5, "text": "If Sarah had had any objection whatsoever for our plan to convert her old bedroom into a home office, she would have brought the matter up when she was here for Christmas, wouldn’t she?"}, {"n": 6, "text": "I personally was left speechless by this performance, and it would appear that the same was true for everyone else present. So, on the behalf of our local council and all here in the audience today, I’d like to thank the orchestra for a quite fabulous experience."}, {"n": 7, "text": "Ismael borrowed a significant amount of capital in order to set up his business, but he’s confident of breaking it even within the first year, as there appears to be a substantial market for his services abroad."}, {"n": 8, "text": "This image shows what, at least with first sight, appears to be some type of bird caring for its eggs. But then, a closer look reveals that it’s not. This is the platypus – an egg-laying creature covered in waterproof fur, and one of nature’s oddest and oldest mammals."}, {"n": 9, "text": "John felt mixed emotions as he cleared his desk. It hadn’t been a snap decision at all for him to hand in notice. He had been growing less and less content at work for a while, and had finally decided he would need to look elsewhere to pursue his career."}, {"n": 10, "text": "Let’s not mention what just happened when Amy’s parents come to fetch her. In all, Amy has never picked on any of the kids at the nursery before and, judging from how nicely she’s playing with Jimmy now, she regrets teasing him."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (11,'{"parts": [{"id": "dictation", "points": 15, "text": "I offered my aunt a modest wedge, but only as her cheerful expression descended into a deep frown did I suddenly recollect the extent to which she loathed strong cheese. We fought in vain to prevent filthy flood water from penetrating the walls. We never stood a chance. My youngest daughter’s written a tale about a little lost lamb that climbs to the peak of a high mountain seeking its mother. It’s dreadful. I’m aware that I came up with the proposal myself, but the idea of knitting each other sweaters somehow doesn’t appeal to me now. It’s an absurd plan. Do I have wrinkles? The crash was an appalling tragedy, and we’re all still grieving the loss of the crew."}, {"id": "oral", "points": 10, "keys": {"1": "a", "2": "c", "3": "a", "4": "a", "5": "c", "6": "b", "7": "b", "8": "c", "9": "b", "10": "b"}, "teacher": {"1": "What do stubborn people tend to resist?", "2": "Today, my brother has a fringe that he didn’t have yesterday. What could explain this?", "3": "Which of these is a natural response if someone burgles you?", "4": "I walk into my house holding some weeds. Where did I probably get them from?", "5": "Which of these can be launched?", "6": "Where are our knuckles?", "7": "Which suggests that someone might be about to drop off?", "8": "What can be a consequence of undertaking a lot at work?", "9": "Which of these is something we can hear?", "10": "Dina discovered that the house she was planning to purchase came with a garden shed. Why might she have been happy to hear that?"}}, {"id": "gap", "points": 5, "accept": {"1": ["worn"], "2": ["question"], "3": ["come"], "4": ["worth"], "5": ["lift"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "b", "3": "c", "4": "c", "5": "a", "6": "c", "7": "a", "8": "b", "9": "b", "10": "a"}}, {"id": "err", "points": 10, "accept": {"1": ["I really sympathize with Alan. If you hadn’t all burst out laughing when he started dancing, he wouldn’t have got so embarrassed and might well have enjoyed the party. It’s such a shame. You know how socially awkward he is."], "2": ["I had never been expected to work around the clock such a lot prior to being recruited by this firm, but, by and large, I’m not complaining."], "3": ["A jigsaw puzzle is comprised of numerous small, normally wooden or cardboard pieces of various shapes which, once fitted together in the correct manner, form one large picture."], "4": ["I assumed we would be in serious trouble now, as today is the deadline for paying off our debt. As it happens, however, Derek has private funds available and has granted us permission to access them temporarily."], "5": ["If Sarah had had any objection whatsoever to our plan to convert her old bedroom into a home office, she would have brought the matter up when she was here for Christmas, wouldn’t she?"], "6": ["I personally was left speechless by this performance, and it would appear that the same was true for everyone else present. So, on behalf of our local council and all here in the audience today, I’d like to thank the orchestra for a quite fabulous experience."], "7": ["Ismael borrowed a significant amount of capital in order to set up his business, but he’s confident of breaking even within the first year, as there appears to be a substantial market for his services abroad."], "8": ["This image shows what, at least at first sight, appears to be some type of bird caring for its eggs. But then, a closer look reveals that it’s not. This is the platypus – an egg-laying creature covered in waterproof fur, and one of nature’s oddest and oldest mammals."], "9": ["John felt mixed emotions as he cleared his desk. It hadn’t been a snap decision at all for him to hand in his notice. He had been growing less and less content at work for a while, and had finally decided he would need to look elsewhere to pursue his career."], "10": ["Let’s not mention what just happened when Amy’s parents come to fetch her. After all, Amy has never picked on any of the kids at the nursery before and, judging from how nicely she’s playing with Jimmy now, she regrets teasing him."]}, "hint": {"1": "Take out “in” – “out laughing”", "2": "Change “be” to “being” – “to being recruited”", "3": "Add “of” – “comprised of numerous”", "4": "Add “it” – “As it happens”", "5": "Change “for” to “to” – “whatsoever to our”", "6": "Take out “the” – “on behalf”", "7": "Take out “it” – “breaking even”", "8": "Change “with” to “at” – “least at first”", "9": "Add “his” – “in his notice”", "10": "Change “In” to “After” – “parents. After all”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (12,45,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "oral", "title": "Part 2 · Listening", "instr": "Listen to your teacher’s questions. Choose the correct answer (a, b or c).", "points": 10, "items": [{"n": 1, "opts": {"a": "They hope you will buy something.", "b": "They sense that you lack confidence.", "c": "They think that you are attractive."}}, {"n": 2, "opts": {"a": "a fast-flowing stream", "b": "an electric kettle", "c": "an aggressive dog"}}, {"n": 3, "opts": {"a": "a pool", "b": "a room", "c": "a bed"}}, {"n": 4, "opts": {"a": "priceless", "b": "countless", "c": "worthless"}}, {"n": 5, "opts": {"a": "our eyes", "b": "our fingers", "c": "our jaws"}}, {"n": 6, "opts": {"a": "when they’re suffering from thirst", "b": "when they’re feeling exhausted", "c": "when they’re experiencing freezing temperatures"}}, {"n": 7, "opts": {"a": "complain excessively", "b": "knock stuff over", "c": "lack social skills"}}, {"n": 8, "opts": {"a": "in a hospital", "b": "on a farm", "c": "at a shopping centre"}}, {"n": 9, "opts": {"a": "John", "b": "Mark", "c": "Peter"}}, {"n": 10, "opts": {"a": "waddle", "b": "topple", "c": "dangle"}}]}, {"id": "gap", "title": "Part 3 · Gap fill", "instr": "Write ONE word in each gap.", "points": 5, "items": [{"n": 1, "q": "Tigers can be distinguished from other large cats first and ____ by their stripes."}, {"n": 2, "q": "Southern England is currently experiencing a ____, with temperatures expected to remain above 30°C for at least a fortnight."}, {"n": 3, "q": "We’re very lucky, I suppose. We’re on excellent ____ with all our neighbours."}, {"n": 4, "q": "Tony’s certainly affluent, but he ____ every penny he’s got; his grandparents were an immensely wealthy couple. Tony’s never even had a job."}, {"n": 5, "q": "When you come over to London, don’t worry about booking accommodation. We’ll be more than happy to ____ you up at our place."}]}, {"id": "mc", "title": "Part 4 · Multiple choice", "instr": "Choose the correct answer.", "points": 10, "items": [{"n": 1, "q": "Passengers wishing to ____ at the next station should move to the front of the carriage, owing to the short platform.", "opts": {"a": "part", "b": "alight", "c": "descend"}}, {"n": 2, "q": "I ____ as I walked onto the stage to collect my award, but only slightly; I didn’t fall over.", "opts": {"a": "mumbled", "b": "stumbled", "c": "tumbled"}}, {"n": 3, "q": "My brother is highly trained in unarmed combat, but he has never once ____ to violence to resolve an argument.", "opts": {"a": "stretched", "b": "inclined", "c": "resorted"}}, {"n": 4, "q": "During the summer, there is a risk of passengers ____ out in hot and overcrowded train carriages.", "opts": {"a": "passing", "b": "fading", "c": "dropping"}}, {"n": 5, "q": "We invested a lot into our business, and, in the long ____, that turned out to have been a wise decision.", "opts": {"a": "story", "b": "plan", "c": "run"}}, {"n": 6, "q": "I know this sounds awful but part of me had hoped they would get ____ with the crime.", "opts": {"a": "off", "b": "away", "c": "out"}}, {"n": 7, "q": "Isa seemed to take ____ Lily from the moment they first met, and now they’re best friends.", "opts": {"a": "to", "b": "after", "c": "with"}}, {"n": 8, "q": "I highly doubt that David ____ on any of us as anything more than a colleague; he’s always so suspicious of people, isn’t he?", "opts": {"a": "looks", "b": "plans", "c": "leans"}}, {"n": 9, "q": "Unfortunately, the deal has ____ through, so we need to make new plans.", "opts": {"a": "slipped", "b": "fallen", "c": "broken"}}, {"n": 10, "q": "You shouldn’t take anything Tom says ____; he just says stuff without thinking half the time.", "opts": {"a": "sincerely", "b": "sensibly", "c": "seriously"}}]}, {"id": "err", "title": "Part 5 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 10, "items": [{"n": 1, "text": "Byron dialled the mobile number Sandra had jotted down for him at the conference, but couldn’t get himself through to her, so he called her company headquarters and asked the receptionist to put him through to her office."}, {"n": 2, "text": "Don’t get me wrong: I love how spacious our detached property is, but I’d gladly swap it round for your terraced house. I reckon the key to being happy in any home is the location, and your suburb would be just right for us and the kids."}, {"n": 3, "text": "I think you’ve convinced yourself that it’s entirely normal for couples to row, fall out with each other, and then make up for each other over and over again. Take it from me, it’s not. It’s a sign that something’s not at all right."}, {"n": 4, "text": "The lesson got out of control because Sam is nothing like assertive with the students as he needs to be. That class would have been far less rowdy if he had been capable of coming across more confidently."}, {"n": 5, "text": "There was noticeable friction among certain members of the board, and the chair was forced on several occasions to remind them of the importance of sticking against the agenda drawn up for the meeting."}, {"n": 6, "text": "In the event of a security alert, an alarm will be heard throughout the store. You should immediately make way directly to your nearest exit in an orderly fashion. Members of staff will be on hand on each floor to direct and assist you."}, {"n": 7, "text": "A certain senior employee, whose name I have recently been made aware of, has been spreading out false rumours that I plan to take over this department and make staff redundant. Nothing could be further from the truth, Sandra, I assure you."}, {"n": 8, "text": "I had assumed that we were all determined to try our utmost to resolve this industrial conflict, so it was the most bewildering to receive news that your union is reluctant to meet us in London and negotiate a way to end it."}, {"n": 9, "text": "I couldn’t make out which one it was, but the boy I witnessed catching fire to my shed last night was definitely one of the Jones brothers. The whole garden’s in chaos now, and, regardless of how young they are, someone should be arrested!"}, {"n": 10, "text": "Your playing career’s officially over, but I’d sooner leave the club myself than lose you. You’ve already tried your hand at coaching, and we’d love to take you on in that role here. Doubtless you’d be fantastic! So, take a while to think over, and get back to me."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (12,'{"parts": [{"id": "dictation", "points": 15, "text": "How can the babies crawl around with all this clutter on the floor? It’s no longer stuffy, so please close the window now. It’s not a refreshing breeze; it’s an irritating draught. As the hunk of bread, which was nothing but crust, was thrown onto his plate, the prisoner scowled at the guards and shoved his food across the table. Mum was dozing off, but a good dose of caffeine should perk her up. The clerks conscientiously completed each task one by one rather than allowing the burden of their assignments to overwhelm them. We’ve recently experienced an especially harsh drought, so I welcome the rain currently soaking my lawn. Purchasing in bulk should help you to stay under budget, but there’s no guarantee."}, {"id": "oral", "points": 10, "keys": {"1": "c", "2": "c", "3": "a", "4": "a", "5": "c", "6": "b", "7": "b", "8": "a", "9": "b", "10": "c"}, "teacher": {"1": "If someone’s chatting you up, what’s their most likely reason for doing so?", "2": "You can hear a growling sound. Where could it be coming from?", "3": "Which is someone most likely to plunge into?", "4": "Which of these words could describe a painting that is so valuable that nobody can say how much it should sell for?", "5": "Which body parts do we have to use in order to chew?", "6": "When are people most likely to want a nap?", "7": "What might you expect a clumsy person to do?", "8": "If Robert and Julie are in the middle of a ward, where do you think they are?", "9": "John’s very physically unfit, Mark’s not at all sociable, and Peter gets extremely nervous around animals. Who’s least likely to enjoy mingling?", "10": "Which of these verbs basically means “to hang”?"}}, {"id": "gap", "points": 5, "accept": {"1": ["foremost"], "2": ["heatwave"], "3": ["terms"], "4": ["inherited"], "5": ["put"]}}, {"id": "mc", "points": 10, "keys": {"1": "b", "2": "b", "3": "c", "4": "a", "5": "c", "6": "b", "7": "a", "8": "a", "9": "b", "10": "c"}}, {"id": "err", "points": 10, "accept": {"1": ["Byron dialled the mobile number Sandra had jotted down for him at the conference, but couldn’t get through to her, so he called her company headquarters and asked the receptionist to put him through to her office."], "2": ["Don’t get me wrong: I love how spacious our detached property is, but I’d gladly swap it for your terraced house. I reckon the key to being happy in any home is the location, and your suburb would be just right for us and the kids."], "3": ["I think you’ve convinced yourself that it’s entirely normal for couples to row, fall out with each other, and then make up with each other over and over again. Take it from me, it’s not. It’s a sign that something’s not at all right."], "4": ["The lesson got out of control because Sam is nothing like as assertive with the students as he needs to be. That class would have been far less rowdy if he had been capable of coming across more confidently."], "5": ["There was noticeable friction among certain members of the board, and the chair was forced on several occasions to remind them of the importance of sticking to the agenda drawn up for the meeting."], "6": ["In the event of a security alert, an alarm will be heard throughout the store. You should immediately make your way directly to your nearest exit in an orderly fashion. Members of staff will be on hand on each floor to direct and assist you."], "7": ["A certain senior employee, whose name I have recently been made aware of, has been spreading false rumours that I plan to take over this department and make staff redundant. Nothing could be further from the truth, Sandra, I assure you."], "8": ["I had assumed that we were all determined to try our utmost to resolve this industrial conflict, so it was most bewildering to receive news that your union is reluctant to meet us in London and negotiate a way to end it."], "9": ["I couldn’t make out which one it was, but the boy I witnessed setting fire to my shed last night was definitely one of the Jones brothers. The whole garden’s in chaos now, and, regardless of how young they are, someone should be arrested!"], "10": ["Your playing career’s officially over, but I’d sooner leave the club myself than lose you. You’ve already tried your hand at coaching, and we’d love to take you on in that role here. Doubtless you’d be fantastic! So, take a while to think it over, and get back to me."]}, "hint": {"1": "Take out “himself” – “get through”", "2": "Take out “round” – “it for”", "3": "Change “for” to “with” – “up with each”", "4": "Add “as” – “like as assertive”", "5": "Change “against” to “to” – “sticking to the”", "6": "Add “your” – “make your way”", "7": "Take out “out” – “spreading false”", "8": "Take out “the” – “was most”", "9": "Change “catching” to “setting” – “witnessed setting fire”", "10": "Add “it” – “think it over”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
